INSERT INTO book_chapters VALUES ('fifty_marks_of_pharisees', 6, 'Chapter 5 Pharisees are very critical of others in small matters', 5, 5, 6, 6);
INSERT INTO book_chapters VALUES ('fifty_marks_of_pharisees', 7, 'Chapter 6 Pharisees live by rules', 6, 7, 7, 20);
INSERT INTO book_chapters VALUES ('fifty_marks_of_pharisees', 8, 'Chapter 7 Pharisees are motivated by jealousy and hatred', 7, 21, 8, 15);
