INSERT INTO book_chapters VALUES ('god_made_mothers', 7, 'Chapter 5 Teaching Our Children Principles And Not Rules', 14, 18, 17, 23);
INSERT INTO book_chapters VALUES ('god_made_mothers', 8, 'Chapter 6 Teaching Our Children Disciplined Habits', 17, 24, 19, 8);
INSERT INTO book_chapters VALUES ('god_made_mothers', 9, 'Chapter 7 Disciplining Our Children', 19, 9, 22, 13);
INSERT INTO book_chapters VALUES ('god_made_mothers', 10, 'Chapter 8 Encouraging Our Children', 22, 14, 25, 2);
INSERT INTO book_chapters VALUES ('god_made_mothers', 11, 'Chapter 9 Have Patience With Me', 25, 3, 26, 9);
INSERT INTO book_chapters VALUES ('god_made_mothers', 12, 'Chapter 10 A Spirit-Filled Helper', 26, 10, 28, 24);
INSERT INTO book_chapters VALUES ('god_made_mothers', 13, 'Chapter 11 Sitting At The Feet Of Jesus', 28, 25, 31, 15);
INSERT INTO book_chapters VALUES ('god_made_mothers', 14, 'Chapter 12 The Gentle Whisper Of God', 31, 16, 34, 13);
