INSERT INTO book_chapters VALUES ('the_final_triumph', 7, 'Chapter 6 Chapter 6', 93, 23, 108, 25);
INSERT INTO book_chapters VALUES ('the_final_triumph', 8, 'Chapter 7 Chapter 7', 108, 26, 124, 5);
