INSERT INTO book_chapters VALUES ('what_the_lord_has_done_for_me', 18, 'Chapter 17 You are Such a Self-Less Person – Laura Poonen', 28, 17, 30, 7);
INSERT INTO book_chapters VALUES ('what_the_lord_has_done_for_me', 19, 'Chapter 18 You are the Biggest Reason I did not Stray – Sunil Poonen', 30, 8, 31, 17);
